async function fetchTasksCached(cache, key, fetcher, onUpdate) {
  const cached = cache.get(key);
  if (cached) {
    fetcher().then((fresh) => {
      if (JSON.stringify(fresh) !== JSON.stringify(cached)) {
        cache.set(key, fresh);
        onUpdate(fresh);
      }
    });
    return cached;
  }
  const fresh = await fetcher();
  cache.set(key, fresh);
  return fresh;
}

