items.solution:
function toggleTaskOptimistic({ tasks, taskId, patchFn, onOptimisticUpdate, onRollback }) {
  const index = tasks.findIndex((t) => t.id === taskId);
  const optimisticTasks = tasks.map((t) =>
    t.id === taskId ? { ...t, done: !t.done } : t,
  );
  onOptimisticUpdate(optimisticTasks);
  return patchFn(taskId, { done: optimisticTasks[index].done })
    .then(() => optimisticTasks)
    .catch((err) => {
      onRollback(tasks);
      throw err;
    });
}

