function toggleStarOptimistic({ items, itemId, patchFn, onOptimisticUpdate, onRollback }) {
  const index = items.findIndex((i) => i.id === itemId);
  const optimisticItems = items.map((i) =>
    i.id === itemId ? { ...i, starred: !i.starred } : i,
  );
  onOptimisticUpdate(optimisticItems);
  return patchFn(itemId, { starred: optimisticItems[index].starred })
    .then(() => optimisticItems)
    .catch((err) => {
      onRollback(items);
      throw err;
    });
}
